<?php include "auth.php";include "conection.php";$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$v=[];foreach(['nisn','nama_siswa','kelas','jurusan','alamat'] as $k)$v[$k]=trim($_POST[$k]??'');$pw=$_POST['password']??'';if($v['nisn']===''||$v['nama_siswa']===''||$v['kelas']===''||$v['jurusan']==='')$error='NISN, nama, kelas, dan jurusan wajib diisi.';else{$hash=$pw!==''?password_hash($pw,PASSWORD_DEFAULT):null;$s=$conn->prepare("INSERT INTO siswa(nisn,nama_siswa,kelas,jurusan,alamat,password) VALUES(?,?,?,?,?,?)");$s->bind_param("ssssss",$v['nisn'],$v['nama_siswa'],$v['kelas'],$v['jurusan'],$v['alamat'],$hash);if($s->execute()){header("Location: siswa.php");exit;}$error=$s->error;}}?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Siswa</title><link rel="stylesheet" href="./data.css?v=spiderman2026"></head><body><div class="app"><?php include "header.php";?><div class="form-card"><p class="eyebrow">MASTER DATA</p><h1>Tambah Siswa</h1><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>NISN</label><input name="nisn" required></div><div class="form-group"><label>Nama Siswa</label><input name="nama_siswa" required></div><div class="form-group"><label>Kelas</label><input name="kelas" placeholder="XII RPL 1" required></div><div class="form-group"><label>Jurusan</label><input name="jurusan" placeholder="Rekayasa Perangkat Lunak" required></div><div class="form-group"><label>Alamat</label><textarea name="alamat"></textarea></div><div class="form-group"><label>Password Login Siswa</label><input type="password" name="password" autocomplete="new-password" placeholder="Kosongkan jika siswa belum boleh login"></div><div class="actions"><a class="btn btn-secondary" href="siswa.php">Kembali</a><button class="btn btn-primary">Simpan</button></div></form></div><?php include "footer.php";?></div></body></html>